import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Auswahllisten und Kataloge pflegen","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/kataloge.md","filePath":"schild3/kataloge.md"}'),l={name:"schild3/kataloge.md"};function i(h,e,d,o,s,u){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="auswahllisten-und-kataloge-pflegen" tabindex="-1">Auswahllisten und Kataloge pflegen <a class="header-anchor" href="#auswahllisten-und-kataloge-pflegen" aria-label="Permalink to &quot;Auswahllisten und Kataloge pflegen&quot;">​</a></h1><p>Kataloge stellen die Werte für Auswahllisten bereit. Legen Sie benötigte Einträge zuerst hier an und ordnen Sie sie anschließend bei Personen, Unterricht oder Zeugnissen zu.</p><h2 id="kataloge-bedienen" tabindex="-1">Kataloge bedienen <a class="header-anchor" href="#kataloge-bedienen" aria-label="Permalink to &quot;Kataloge bedienen&quot;">​</a></h2><p>Die Anleitung <a href="/schild3/unterricht-kataloge/allgemeine-kataloge-kataloge.html">Katalogeinträge anlegen, sortieren und anzeigen</a> erklärt Einfügen, Löschen, Reihenfolge, Sichtbarkeit und Export. Die Übersicht <a href="/schild3/unterricht-kataloge/schulbezogene-kataloge-kataloge.html">Schulbezogene Kataloge</a> ordnet die schulischen Listen ein. Unterrichtsfächer, Jahrgänge, Klassen und Kurse finden Sie unter <a href="/schild3/unterricht-kataloge.html">Klassen und Unterricht</a>.</p><h2 id="texte-bewertungen-und-einwilligungen-vorbereiten" tabindex="-1">Texte, Bewertungen und Einwilligungen vorbereiten <a class="header-anchor" href="#texte-bewertungen-und-einwilligungen-vorbereiten" aria-label="Permalink to &quot;Texte, Bewertungen und Einwilligungen vorbereiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Wiederkehrende Bemerkungen als Textbausteine hinterlegen</td><td><a href="/schild3/unterricht-kataloge/floskeln-bearbeiten-schulbezogene-kataloge.html">Floskeln</a></td></tr><tr><td>Arten von Einzel- und Zwischenleistungen definieren</td><td><a href="/schild3/unterricht-kataloge/teilleistungs-arten-schulbezogene-kataloge.html">Teilleistungsarten</a></td></tr><tr><td>Datenschutz-Einwilligungen vorbereiten</td><td><a href="/schild3/unterricht-kataloge/dsgvo-einwilligungen-schulbezogene-kataloge.html">DSGVO-Einwilligungen</a></td></tr><tr><td>Verwendete Lernplattformen anlegen</td><td><a href="/schild3/unterricht-kataloge/lernplattformen-schulbezogene-kataloge.html">Lernplattformen</a></td></tr><tr><td>Schulinterne Funktionen vorbereiten</td><td><a href="/schild3/unterricht-kataloge/schulinterne-funktionen-schulbezogene-kataloge.html">Schulinterne Funktionen</a></td></tr><tr><td>Kategorien für Schülervermerke festlegen</td><td><a href="/schild3/unterricht-kataloge/vermerk-arten-schulbezogene-kataloge.html">Vermerkarten</a></td></tr></tbody></table><h2 id="personen-und-kontakte-strukturieren" tabindex="-1">Personen und Kontakte strukturieren <a class="header-anchor" href="#personen-und-kontakte-strukturieren" aria-label="Permalink to &quot;Personen und Kontakte strukturieren&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Schulische Gremien und gemischte Personengruppen bilden</td><td><a href="/schild3/unterricht-kataloge/personengruppen-schulbezogene-kataloge.html">Personengruppen</a></td></tr><tr><td>Verhältnis zum Schulkind bezeichnen</td><td><a href="/schild3/unterricht-kataloge/erzieher-arten-allgemeine-kataloge.html">Erzieherarten</a></td></tr><tr><td>Arten telefonischer Kontakte festlegen</td><td><a href="/schild3/unterricht-kataloge/telef-ansprechpartner-allgemeine-kataloge.html">Telefonische Ansprechpartner</a></td></tr><tr><td>Kategorien für weitere Adressen anlegen</td><td><a href="/schild3/unterricht-kataloge/adress-arten-allgemeine-kataloge.html">Adressarten</a></td></tr><tr><td>Betriebe und allgemeine Kontakte pflegen</td><td><a href="/schild3/unterricht-kataloge/allgemeine-adressen-allgemeine-kataloge.html">Allgemeine Adressen</a></td></tr></tbody></table><p>Individuelle Schülergruppen werden unter <a href="/schild3/suchen-gruppenprozesse.html">Auswahl und Suche</a> angelegt und verwendet.</p><h2 id="schulbesuch-wohnort-und-weitere-merkmale-vorbereiten" tabindex="-1">Schulbesuch, Wohnort und weitere Merkmale vorbereiten <a class="header-anchor" href="#schulbesuch-wohnort-und-weitere-merkmale-vorbereiten" aria-label="Permalink to &quot;Schulbesuch, Wohnort und weitere Merkmale vorbereiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Benötigte NRW-Schulen auswählen</td><td><a href="/schild3/unterricht-kataloge/schulen-in-nrw-allgemeine-kataloge.html">Schulen in NRW</a></td></tr><tr><td>Schulherkunft außerhalb von NRW vorbereiten</td><td><a href="/schild3/unterricht-kataloge/andere-schulen-und-schulnummern-allgemeine-kataloge.html">Andere Schulen und Schulnummern</a></td></tr><tr><td>Orte und ihre Reihenfolge festlegen</td><td><a href="/schild3/unterricht-kataloge/orte-allgemeine-kataloge.html">Orte</a></td></tr><tr><td>Ortsteile für Anschrift und Auswahl ergänzen</td><td><a href="/schild3/unterricht-kataloge/ortsteile-allgemeine-kataloge.html">Ortsteile</a></td></tr><tr><td>Haltestellen für den Schulweg erfassen</td><td><a href="/schild3/unterricht-kataloge/haltestellen-allgemeine-kataloge.html">Haltestellen</a></td></tr><tr><td>Beförderungsarten vorbereiten</td><td><a href="/schild3/unterricht-kataloge/fahrschueler-arten-allgemeine-kataloge.html">Fahrschülerarten</a></td></tr><tr><td>Benötigte Förderschwerpunkte bereitstellen</td><td><a href="/schild3/unterricht-kataloge/foerderschwerpunkte-allgemeine-kataloge.html">Förderschwerpunkte</a></td></tr><tr><td>Gründe für Sportbefreiungen pflegen</td><td><a href="/schild3/unterricht-kataloge/sportbefreiungen-allgemeine-kataloge.html">Sportbefreiungen</a></td></tr><tr><td>Entlassgründe und Bemerkungen vorbereiten</td><td><a href="/schild3/unterricht-kataloge/entlassungs-bemerkungen-allgemeine-kataloge.html">Entlassungsbemerkungen</a></td></tr><tr><td>Konfession, Statistik- und Zeugnisbezeichnung zuordnen</td><td><a href="/schild3/unterricht-kataloge/konfessionen-allgemeine-kataloge.html">Konfessionen</a></td></tr></tbody></table>',11)])])}const k=t(l,[["render",i]]);export{c as __pageData,k as default};
